function CastingLadlePreheatBurnerMaker.completeMaking(m) local q=1.0+(CastingLadlePreheatBurnerMaker.getQualityBonus()/100); if CastingLadlePreheatBurnerMaker.maker then q=q+(CastingLadlePreheatBurnerMaker.maker.skill/140) end; q=math.min(2.5,q); CastingLadlePreheatBurnerMaker.productStock[m.productType]=(CastingLadlePreheatBurnerMaker.productStock[m.productType] or 0)+m.quantity; CastingLadlePreheatBurnerMaker.totalProducts=CastingLadlePreheatBurnerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CastingLadlePreheatBurnerMaker.maker then CastingLadlePreheatBurnerMaker.maker.itemsMade=CastingLadlePreheatBurnerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CastingLadlePreheatBurnerMaker.maker.skill=math.min(100,CastingLadlePreheatBurnerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gorilnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"castingladlepreheatburner.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
